# Decode an octal mode like 755 into rwx text, one digit at a time.
def rwx(digit):
    # r=4, w=2, x=1: test each bit of the digit
    return ("r" if digit & 4 else "-") + ("w" if digit & 2 else "-") + ("x" if digit & 1 else "-")

def decode(mode):
    return "".join(rwx(int(d)) for d in str(mode))

for mode in (755, 644, 600, 700):
    print(mode, "->", decode(mode))

# Directory meaning: x is needed to enter, r to list, w to create/delete entries
def dir_can(mode_digit):
    return {"list names": bool(mode_digit & 4), "enter/access": bool(mode_digit & 1),
            "create/delete": bool(mode_digit & 2 and mode_digit & 1)}

print("dir r-x for others:", dir_can(5))
print("dir r-- for others:", dir_can(4))
print("dir -wx for others:", dir_can(3))

import os, time

def state(pid):
    with open("/proc/%d/stat" % pid) as f:
        return f.read().split()[2]            # field 3 is the state letter

pid = os.fork()
if pid == 0:
    os._exit(7)                                # child exits immediately

time.sleep(0.3)                                # parent has not called wait yet
print("child state before wait:", state(pid), "(Z = zombie)")
done, status = os.waitpid(pid, 0)              # reaping removes the table entry
print("reaped pid ok:", done == pid, "exit status:", os.WEXITSTATUS(status))
try:
    state(pid)
except FileNotFoundError:
    print("after waitpid: /proc entry is gone")

# Reap many children safely: loop with WNOHANG, as a SIGCHLD handler should
kids = []
for i in range(3):
    c = os.fork()
    if c == 0:
        os._exit(i)
    kids.append(c)
time.sleep(0.3)
reaped = []
while True:
    try:
        p, s = os.waitpid(-1, os.WNOHANG)
    except ChildProcessError:
        break
    if p == 0:
        break
    reaped.append(os.WEXITSTATUS(s))
print("reaped statuses:", sorted(reaped))
